pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {PoCGame} from "../src/PoCGame.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    PoCGame c;

    function setUp() public {
        c = new PoCGame(address(this), 0);
    }

    function _runTest(uint256 a) internal {
        try c.AdjustDifficulty(a) {} catch { return; }
        assertTrue(c.currentDifficulty() == a);
    }

    function testFuzz_runTest(uint256 a) public {
        _runTest(a);
    }

    receive() external payable {}
}
